 if(!crop.hidden){const b=r.roi;crop.style.left=b.x/r.width*100+'%';crop.style.top=b.y/r.height*100+'%';crop.style.width=b.width/r.width*100+'%';crop.style.height=b.height/r.height*100+'%';crop.style.borderWidth=(1.5/actualZoom)+'px';$('.crop-tag').textContent=cropLabel(r);$('.crop-tag').style.transform=`scale(${1/actualZoom})`;$('.crop-tag').style.transformOrigin='left bottom';$$('.crop-handle').forEach(el=>el.style.transform=`scale(${1/actualZoom})`);$('#lane-lines').innerHTML=Array.from({length:r.lanes},(_,i)=>`<span class="lane-number" style="left:${(i+.5)/r.lanes*100}%;transform:translateX(-50%) scale(${1/actualZoom});transform-origin:top">${i+1}</span>${i?`<span class="lane-line" style="left:${i/r.lanes*100}%"></span>`:''}`).join('');}
